        }
        java.util.Map<String, java.util.List<String>> graph = new java.util.HashMap<>();
        for (int[] path : paths) {
            if (path == null || path.length != 4) continue;
            String a = java.util.Arrays.toString(new int[]{path[0], path[1]});
            String b = java.util.Arrays.toString(new int[]{path[2], path[3]});
            graph.computeIfAbsent(a, k -> new java.util.ArrayList<>()).add(b);
            graph.computeIfAbsent(b, k -> new java.util.ArrayList<>()).add(a);
        }
        String startKey = java.util.Arrays.toString(start);
        String endKey = java.util.Arrays.toString(end);
        if (startKey.equals(endKey)) return "can be travelled";
        if (!graph.containsKey(startKey) || !graph.containsKey(endKey)) return "cannot be travelled";
        java.util.Set<String> visited = new java.util.HashSet<>();
        java.util.Queue<String> q = new java.util.LinkedList<>();
        q.add(startKey);
        visited.add(startKey);
        while (!q.isEmpty()) {
            String cur = q.poll();
            if (cur.equals(endKey)) return "can be travelled";
            for (String nb : graph.getOrDefault(cur, java.util.Collections.emptyList())) {
                if (!visited.contains(nb)) {
                    visited.add(nb);
                    q.add(nb);
                }
            }
        }
        return "cannot be travelled";
