public boolean hasAllCodes(String s, int k) {
    if (s == null || k <= 0) return false;
    int n = s.length();
    long total = 1L << k;
    if (n < total) return false;
    if (k > 20) { // use HashSet to avoid large array
        java.util.HashSet<Long> seen = new java.util.HashSet<>();
        long mask = total - 1;
        long code = 0;
        for (int i = 0; i < n; i++) {
            code = ((code << 1) & mask) | (s.charAt(i) - '0');
            if (i >= k - 1) {
                seen.add(code);
                if (seen.size() == total) return true;
            }
        }
        return seen.size() == total;
    } else {
        int totalInt = (int) total;
        boolean[] seen = new boolean[totalInt];
        int mask = totalInt - 1;
        int code = 0;
        for (int i = 0; i < n; i++) {
            code = ((code << 1) & mask) | (s.charAt(i) - '0');
            if (i >= k - 1) {
                seen[code] = true;
            }
        }
        for (boolean b : seen) {
            if (!b) return false;
        }
        return true;
    }
}

