public int minInsertions(String s) {
    if (s == null || s.isEmpty()) {
        return 0;
    }
    int insertions = 0;
    int balance = 0; // number of unmatched '('
    for (int i = 0; i < s.length(); i++) {
        char c = s.charAt(i);
        if (c == '(') {
            balance++;
        } else if (c == ')') {
            if (balance == 0) {
                // Need an opening bracket before this ')'
                insertions++;
            } else {
                balance--; // match with a previous '('
            }
        } else {
            // If unexpected character, ignore or throw exception
            // Here we choose to ignore it
        }
    }
    // Any remaining unmatched '(' need a closing ')'
    insertions += balance;
    return insertions;
}

