public static int[] diagonalOrder(int[][] mat) {
    if (mat == null || mat.length == 0 || mat[0] == null || mat[0].length == 0) {
        return new int[0];
    }
    int m = mat.length;
    int n = mat[0].length;
    int[] res = new int[m * n];
    int idx = 0;
    try {
        for (int k = 0; k <= m + n - 2; k++) {
            if ((k & 1) == 0) {
                int i = Math.min(k, m - 1);
                int j = k - i;
                while (i >= 0 && j < n) {
                    res[idx++] = mat[i][j];
                    i--;
                    j++;
                }
            } else {
                int j = Math.min(k, n - 1);
                int i = k - j;
                while (j >= 0 && i < m) {
                    res[idx++] = mat[i][j];
                    i++;
                    j--;
                }
            }
        }
    } catch (Exception e) {
        return new int[0];
    }
    return res;
}

public static int findSmallestInteger(int n) {
    char[] digits = String.valueOf(n).toCharArray();
    int i = digits.length - 2;
    while (i >= 0 && digits[i] >= digits[i+1]) i--;
    if (i < 0) return -1;
    int j = digits.length - 1;
    while (digits[j] <= digits[i]) j--;
    // swap
    char temp = digits[i];
    digits[i] = digits[j];
    digits[j] = temp;
    // reverse suffix
    int left = i+1, right = digits.length-1;
    while (left < right) {
        char t = digits[left];
        digits[left] = digits[right];
        digits[right] = t;
        left++; right--;
    }
    // convert to int
    long result = 0;
    for (char c : digits) {
        result = result*10 + (c - '0');
        if (result > Integer.MAX_VALUE) return -1; // overflow
    }
    return (int) result;
}

