public static int calculateUniqueSum(int[] nums) {
    if (nums == null || nums.length == 0) {
        return 0;
    }
    java.util.Set<Integer> seen = new java.util.HashSet<>();
    java.util.Set<Integer> unique = new java.util.HashSet<>();
    for (int num : nums) {
        if (seen.contains(num)) {
            unique.remove(num);
        } else {
            seen.add(num);
            unique.add(num);
        }
    }
    int sum = 0;
    for (int val : unique) {
        sum += val;
    }
    return sum;
}

public static int minPerfectSquareSum(int n) {
    if (n <= 0) {
        return 0;
    }
    // Check if n is a perfect square
    int sqrtN = (int) Math.sqrt(n);
    if (sqrtN * sqrtN == n) {
        return 1;
    }
    // Check if n can be expressed as sum of two perfect squares
    for (int i = 1; i <= sqrtN; i++) {
        int remainder = n - i * i;
        int sqrtR = (int) Math.sqrt(remainder);
        if (sqrtR * sqrtR == remainder) {
            return 2;
        }
    }
    // Legendre's three-square theorem
    int temp = n;
    while (temp % 4 == 0) {
        temp /= 4;
    }
    if (temp % 8 == 7) {
        return 4;
    }
    return 3;
}

public static String reverseWords(String s) {
    if (s == null || s.isEmpty()) {
        return s;
    }
    StringBuilder result = new StringBuilder();
    int start = 0;
    for (int i = 0; i < s.length(); i++) {
        if (s.charAt(i) == ' ') {
            for (int j = i - 1; j >= start; j--) {
                result.append(s.charAt(j));
            }
            result.append(' ');
            start = i + 1;
        }
    }
    for (int j = s.length() - 1; j >= start; j--) {
        result.append(s.charAt(j));
    }
    return result.toString();
}
